-- ============================================================================
-- MONDIALI 2026 - Database per esercitazioni SQL
-- ============================================================================
--
-- Questo script crea il database `mondiali` e tre tabelle denormalizzate:
--   * squadre    (48 righe)
--   * partite    (104 righe)
--   * giocatori  (1248 righe)
--
-- Non ci sono chiavi esterne: i dati sono volutamente ripetuti nelle tabelle,
-- così le query possono usare una sola tabella alla volta (niente JOIN).
--
-- COME IMPORTARE (terminale):
--     mysql -u root -p < mondiali.sql
-- oppure, da dentro il client MariaDB:
--     SOURCE /percorso/completo/mondiali.sql;
--
-- ATTENZIONE: se il database `mondiali` esiste già, le tre tabelle
-- `squadre`, `partite` e `giocatori` vengono eliminate e ricreate.
-- Le altre eventuali tabelle del database non vengono toccate.
-- ============================================================================

SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS mondiali
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_unicode_ci;

USE mondiali;

DROP TABLE IF EXISTS giocatori;
DROP TABLE IF EXISTS partite;
DROP TABLE IF EXISTS squadre;

-- ----------------------------------------------------------------------------
-- Tabella `squadre`: una riga per ciascuna delle 48 nazionali partecipanti.
-- ----------------------------------------------------------------------------
CREATE TABLE squadre (
  id            INT              NOT NULL,
  nome          VARCHAR(60)      NOT NULL,
  codice        CHAR(3)          NOT NULL,
  gruppo        CHAR(1)          NOT NULL,
  confederazione VARCHAR(20)     NOT NULL,
  ranking_fifa  SMALLINT         NOT NULL,
  elo           SMALLINT         NOT NULL,
  allenatore     VARCHAR(80)     NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_squadre_codice (codice),
  UNIQUE KEY uk_squadre_nome (nome)
) ENGINE=InnoDB;

-- ----------------------------------------------------------------------------
-- Tabella `partite`: una riga per ciascuna delle 104 partite del torneo.
-- I nomi di squadre, stadio, arbitro e miglior giocatore sono ripetuti
-- (denormalizzazione), quindi non servono JOIN per leggerli.
-- `girone` è NULL per le partite a eliminazione diretta.
-- `rigori_casa` e `rigori_trasferta` sono NULL se la partita non è finita
-- ai calci di rigore.
-- ----------------------------------------------------------------------------
CREATE TABLE partite (
  id                    INT               NOT NULL,
  data                  DATE              NOT NULL,
  ora                   TIME              NOT NULL,
  fase                  VARCHAR(30)       NOT NULL,
  girone                CHAR(1)           NULL,
  stadio                VARCHAR(80)       NOT NULL,
  citta                 VARCHAR(50)       NOT NULL,
  paese                 VARCHAR(30)       NOT NULL,
  capienza              INT               NOT NULL,
  squadra_casa          VARCHAR(60)       NOT NULL,
  codice_casa           CHAR(3)           NOT NULL,
  squadra_trasferta     VARCHAR(60)       NOT NULL,
  codice_trasferta      CHAR(3)           NOT NULL,
  gol_casa              TINYINT           NOT NULL,
  gol_trasferta         TINYINT           NOT NULL,
  rigori_casa           TINYINT           NULL,
  rigori_trasferta      TINYINT           NULL,
  tipo_risultato        VARCHAR(15)       NOT NULL,
  xg_casa               DECIMAL(4,2)      NOT NULL,
  xg_trasferta          DECIMAL(4,2)      NOT NULL,
  possesso_casa         TINYINT           NOT NULL,
  possesso_trasferta    TINYINT           NOT NULL,
  tiri_casa             SMALLINT         NOT NULL,
  tiri_trasferta        SMALLINT         NOT NULL,
  tiri_in_porta_casa    SMALLINT         NOT NULL,
  tiri_in_porta_trasferta SMALLINT         NOT NULL,
  falli_casa            TINYINT           NOT NULL,
  falli_trasferta       TINYINT           NOT NULL,
  arbitro               VARCHAR(60)       NOT NULL,
  nazionalita_arbitro   VARCHAR(40)       NOT NULL,
  miglior_giocatore     VARCHAR(80)       NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB;

-- ----------------------------------------------------------------------------
-- Tabella `giocatori`: una riga per ciascuno dei 1248 giocatori convocati.
-- `squadra`, `codice_squadra` e `confederazione` ripetono i dati della
-- nazionale (denormalizzazione), quindi non servono JOIN per leggerli.
-- Le statistiche `presenze`, `minuti`, `gol`, `assist`, `ammonizioni`,
-- `espulsioni` e `autogol` si riferiscono al solo torneo 2026.
-- `presenze_carriera` e `gol_carriera` sono i totali in nazionale.
-- `valore_mercato` è espresso in euro.
-- `porta_inviolata`, `parate` e `gol_subiti` sono valorizzati solo per i
-- portieri; per gli altri ruoli valgono NULL.
-- ----------------------------------------------------------------------------
CREATE TABLE giocatori (
  id                  INT               NOT NULL,
  nome                VARCHAR(80)       NOT NULL,
  squadra             VARCHAR(60)       NOT NULL,
  codice_squadra      CHAR(3)           NOT NULL,
  confederazione      VARCHAR(20)       NOT NULL,
  ruolo               VARCHAR(15)       NOT NULL,
  club                VARCHAR(80)       NOT NULL,
  valore_mercato      INT               NOT NULL,
  presenze_carriera   SMALLINT         NOT NULL,
  gol_carriera        SMALLINT         NOT NULL,
  data_nascita        DATE              NOT NULL,
  altezza_cm          SMALLINT          NOT NULL,
  presenze            SMALLINT         NOT NULL,
  minuti              SMALLINT         NOT NULL,
  gol                 TINYINT           NOT NULL,
  assist              TINYINT           NOT NULL,
  ammonizioni         TINYINT           NOT NULL,
  espulsioni          TINYINT           NOT NULL,
  autogol             TINYINT           NOT NULL,
  porta_inviolata     TINYINT           NULL,
  parate              SMALLINT          NULL,
  gol_subiti          TINYINT           NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB;

