-- ============================================================================
-- CONTROLLI FINALI: devono restituire rispettivamente 48, 104 e 1248
-- ============================================================================
SELECT COUNT(*) AS numero_squadre FROM squadre;
SELECT COUNT(*) AS numero_partite FROM partite;
SELECT COUNT(*) AS numero_giocatori FROM giocatori;
